node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const productIds = ['PROD-3E35A7', 'PROD-4ED2E3', 'PROD-39F904', 'PROD-FA0948'];

// Check products table columns
const pCols = db.pragma('table_info(products)');
console.log('=== products columns ===');
console.log(pCols.map(c => c.name));

for (const pid of productIds) {
  const prod = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
  console.log('\n=== Product: ' + pid + ' ===');
  console.log(JSON.stringify(prod, null, 2));
}

// Check if there are variants
const vCols = db.pragma('table_info(rt_variants)');
console.log('\n=== rt_variants columns ===');
console.log(vCols.map(c => c.name));

for (const pid of productIds) {
  const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(pid);
  if (variants.length > 0) {
    console.log('\n=== Variants for ' + pid + ' ===');
    console.log(JSON.stringify(variants, null, 2));
  }
}

// Also get customer details
const user = db.prepare(\"SELECT * FROM users WHERE user_id = 'user_2f61840f'\").get();
console.log('\n=== Customer ===');
console.log(JSON.stringify(user, null, 2));
" 2>&1
